// Conversational style modifiers for English
function applyEnglishVariation(base: SentenceDef, cycle: number, category: string, index: number): SentenceDef {
  if (cycle === 0) return base;

  const prefixes: { en: string; viPhonetics: string; viMeaning: string; intonation: string }[] = [
    { en: 'Could you please confirm if ', viPhonetics: 'Kút diu phli-z cơn-phơm íp ', viMeaning: 'Bạn có thể vui lòng xác nhận giúp xem ', intonation: '↗ Lên giọng lịch sự' },
    { en: 'Excuse me, would it be possible to know whether ', viPhonetics: 'Ích-s kiu-z mi, út ít bi phót-xi-bồ thừ nâu ué-đơ ', viMeaning: 'Xin lỗi, liệu có thể cho tôi biết xem ', intonation: '↗ Lên giọng hỏi khéo' },
    { en: 'I was wondering if ', viPhonetics: 'Ai uơ-z uăn-đơ-rinh íp ', viMeaning: 'Tôi đang tự hỏi không biết ', intonation: '↘ Giọng điệu tò mò, nhẹ nhàng' },
    { en: 'Before we proceed today, can we ensure that ', viPhonetics: 'Bi-pho uy p-rô-xít tu-đây, cen uy in-sua đát ', viMeaning: 'Trước khi chúng ta tiếp tục hôm nay, liệu chúng ta có thể đảm bảo rằng ', intonation: '↗ Lên giọng đề xuất' },
    { en: 'Shall we take a quick moment and check if ', viPhonetics: 'Seo uy thêk ơ quých mô-mừn-t en check íp ', viMeaning: 'Chúng ta cùng dành chút thời gian kiểm tra xem ', intonation: '↗ Rủ rê hợp tác' },
    { en: 'Just to double-check from our side, ', viPhonetics: 'Chắt thừ đắp-bồ check ph-rầm ao-ơ xait, ', viMeaning: 'Chỉ để kiểm tra kỹ lại từ phía chúng tôi, ', intonation: '↘ Cẩn trọng, chu đáo' },
    { en: 'Thank you in advance! Could you also verify that ', viPhonetics: 'Thenk kiu in ơ-đ-văn-s! Kút diu ôn-sâu vé-ri-phai đát ', viMeaning: 'Cảm ơn bạn trước nhé! Bạn có thể xác minh thêm giúp xem ', intonation: '↗ Biết ơn và thỉnh cầu' },
    { en: 'Pardon me, did you mention earlier that ', viPhonetics: 'Pa-đừn mi, đít diu mén-sừn ơ-li-ơ đát ', viMeaning: 'Thứ lỗi cho tôi, lúc nãy bạn có nhắc đến việc ', intonation: '↗ Lên giọng hỏi lại cho rõ' },
    { en: 'That sounds really great, let us make sure ', viPhonetics: 'Đát khao-n-d-z ri-li g-rết, lét ắt mếk sua ', viMeaning: 'Nghe thật tuyệt vời, chúng ta hãy đảm bảo ', intonation: '↘ Vui vẻ, dứt khoát' },
  ];

  const mod = prefixes[(cycle - 1) % prefixes.length];
  const lowerOrig = base.original.charAt(0).toLowerCase() + base.original.slice(1);
  const lowerPhonetics = base.phoneticsVi.charAt(0).toLowerCase() + base.phoneticsVi.slice(1);

  return {
    original: `${mod.en}${lowerOrig}`,
    phoneticsVi: `${mod.viPhonetics}${lowerPhonetics}`,
    meaningVi: `${mod.viMeaning}${base.meaningVi.toLowerCase()}`,
    intonation: mod.intonation,
    tip: `${base.tip} Nhấn rõ nhịp câu và giao tiếp tự tin.`,
  };
}

function generateEnglishSentence(category: string, index: number): PracticeItem {
  const id = `en-${category.replace(/[^a-zA-Z0-9]/g, '-').toLowerCase()}-${index}`;

  if (category === 'Kinh tế, tài chính, kế toán') {
    return getFinanceEnglishSentence(index);
  }

  if (category === 'Lễ tân khách sạn') {
    const p = getFrontDeskPhrase(index);
    return {
      id,
      language: 'en',
      category,
      original: p.original,
      phoneticsVi: p.phoneticsVi,
      meaningVi: p.meaningVi,
      intonation: p.intonation,
      tip: p.tip,
    };
  }

  const seedList = EN_SEEDS[category] || EN_SEEDS['Hàng ngày'];
  const coreIdx = (index - 1) % seedList.length;
  const cycle = Math.floor((index - 1) / seedList.length);
  const p = applyEnglishVariation(seedList[coreIdx], cycle, category, index);

  return {
    id,
    language: 'en',
    category,
    original: p.original,
    phoneticsVi: p.phoneticsVi,
    meaningVi: p.meaningVi,
    intonation: p.intonation,
    tip: p.tip,
  };
}

