export function getCategoryPhrases(category: string, lang: 'en' | 'zh' | 'km' | 'lo'): PracticeItem[] {
  const items: PracticeItem[] = [];
  const baseCount = category === 'Kinh tế, tài chính, kế toán' ? 500 : 210; // 500 câu chuyên đề Kinh tế, tài chính, kế toán & hơn 200 câu cho mỗi chủ đề khác

  for (let i = 1; i <= baseCount; i++) {
    const item = createThemedPhrase(category, lang, i);
    items.push(item);
  }

  return items;
}

function createThemedPhrase(category: string, lang: 'en' | 'zh' | 'km' | 'lo', index: number): PracticeItem {
  if (lang === 'en') {
    return generateEnglishSentence(category, index);
  }
  if (lang === 'zh') {
    return generateChineseSentence(category, index);
  }
  if (lang === 'km') {
    return generateKhmerSentence(category, index);
  }
  return generateLaoSentence(category, index);
}

export function buildPracticeLibrary(): PracticeItem[] {
  const library: PracticeItem[] = [];
  const mainCategories = PRACTICE_CATEGORIES.filter((c) => c !== 'Tất cả');

  for (const cat of mainCategories) {
    library.push(...getCategoryPhrases(cat, 'en'));
    library.push(...getCategoryPhrases(cat, 'zh'));
    library.push(...getCategoryPhrases(cat, 'km'));
    library.push(...getCategoryPhrases(cat, 'lo'));
  }

  return library;
}

export const ALL_PRACTICE_ITEMS: PracticeItem[] = buildPracticeLibrary();
